import{_ as t,o as a,c as r,ak as i}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy learner and session guide","description":"Draft for GDD v2, October 23, 2026. Sean finalizes wording against the tested build. Design steps below are not proof that every screen exists.","frontmatter":{"title":"Chainy learner and session guide","description":"Draft for GDD v2, October 23, 2026. Sean finalizes wording against the tested build. Design steps below are not proof that every screen exists.","source":"docs/user-guide.md","category":"Guides & tooling","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/user-guide.md","filePath":"content/docs/user-guide.md"}'),o={name:"content/docs/user-guide.md"};function s(n,e,c,l,d,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<div><h1 id="chainy-learner-and-session-guide">Chainy learner and session guide<a class="header-anchor" href="#chainy-learner-and-session-guide" aria-label="Link to this section">​</a></h1><p>Draft for GDD v2, October 23, 2026. Sean finalizes wording against the tested build. Design steps below are not proof that every screen exists.</p><h2 id="november-10-core-chapter">November 10 core chapter<a class="header-anchor" href="#november-10-core-chapter" aria-label="Link to this section">​</a></h2><ol><li>Open the offline Android game and select the correct local demo profile. A profile code does not verify identity or recover another phone.</li><li>Move through the compact isometric world and interact with Sean. Dialogue appears over the world; movement pauses while choices are open.</li><li>Follow W01–W04: identify a shareable fictional address, help a resident for 12 coins, review lantern #014 for 8 plus a 1-coin fee, and authorize or cancel. Successful purchase leaves 3 coins. Equipping the owned lantern is free.</li><li>Restore the workshop, then meet Matthew. Inspect that same purchase record, connect three blocks from the trusted checkpoint, and use the original price to reject altered data.</li><li>Restore the beacon and read the demo-chapter completion message. Consult the quest log for objectives and the encyclopedia for explanations.</li></ol><p>All currency, addresses and records are fictional. Never enter real keys, seed phrases, payment details or other secrets. Ask a trusted adult about real-world claims.</p><h2 id="saving-and-recovery">Saving and recovery<a class="header-anchor" href="#saving-and-recovery" aria-label="Link to this section">​</a></h2><p>Wait for confirmed save feedback. If saving fails, use the offered retry; do not restart a purchase to force it through. A retry must not charge or reward twice. Relaunch resumes a supported saved checkpoint, not necessarily the exact animation. Confirm the profile before sharing a device.</p><h2 id="what-is-not-promised-in-this-beta">What is not promised in this beta<a class="header-anchor" href="#what-is-not-promised-in-this-beta" aria-label="Link to this section">​</a></h2><p>AI labeling/training/practice/final-test may appear only if its stretch gate passes. Full-world completion, standalone Wordle, BlockMatch, teacher activation, phone pairing, collection and upload are later scope. A disabled or illustrative screen is not a working feature.</p><h2 id="session-staff">Session staff<a class="header-anchor" href="#session-staff" aria-label="Link to this section">​</a></h2><p>Cryptita Plays community beta testing is November 10, 2026. Use the approved procedure and tested build, explain disclosed limitations, record assistance and collect only permitted evidence. Do not place participant identities in GitHub or public documents. Community feedback does not automatically satisfy school pilot requirements. Pre-final remains November 21.</p></div>',1)])])}const f=t(o,[["render",s]]);export{u as __pageData,f as default};
